//! The renderer's copy of the trusted licence keys (12 §7.4, LIC-003),
//! generated by `cargo xtask types` from `cavea_licence::TRUSTED`, the one
//! list (D-80): a renderer-only customer's licence string is verified in the
//! browser against these, so a key added there reaches the SDK with the next
//! `cargo xtask types`, and `--check` (and this module's test) fails until it
//! has. Each key carries its id, computed here as the server computes it, so
//! the browser needs no SHA-256.

use std::fmt::Write as _;

use anyhow::{Result, anyhow};
use cavea_licence::{PublicKey, TRUSTED};

/// The generated file, relative to the workspace root.
pub const OUTPUT: &str = "packages/renderer/src/generated/licence-keys.ts";

pub fn generate() -> Result<String> {
    let mut out = String::from(
        "// Generated by `cargo xtask types` from `TRUSTED` in \
         crates/cavea-licence/src/keys.rs (D-80).\n\
         // Do not edit: add a key there.\n\n\
         /** An Ed25519 public key a licence may be signed with: its id and its 32 bytes in base64. */\n\
         export type TrustedKey = { readonly id: string; readonly key: string };\n\n\
         /** The keys every build trusts, oldest first. */\n\
         export const TRUSTED_KEYS: readonly TrustedKey[] = [",
    );
    let mut first = true;
    for key in TRUSTED {
        let public =
            PublicKey::from_base64(key).ok_or_else(|| anyhow!("a trusted key does not decode"))?;
        out.push_str(if first { "\n" } else { "" });
        first = false;
        writeln!(
            out,
            "  {{ id: \"{}\", key: \"{}\" }},",
            public.id(),
            public.to_base64()
        )?;
    }
    out.push_str("];\n");
    Ok(out)
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used, reason = "tests")]

    use super::*;

    #[test]
    fn generated_licence_keys_are_current() {
        let committed = std::fs::read_to_string(crate::root().join(OUTPUT)).unwrap_or_default();
        assert!(
            committed == generate().unwrap(),
            "{OUTPUT} is stale: run `cargo xtask types`"
        );
    }
}
